import * as SecureStore from "expo-secure-store";
import { MemoryStoreError } from "./memory-error";

/**
 * Encrypted native memory (owner decision 0001, approved 2026-10-24).
 *
 * Items live in an expo-sqlite database built with SQLCipher. SQLite does not encrypt by default, so the store does not
 * rely on that: the `useSQLCipher` plugin option is set in app.config.ts, and before anything is written the store
 * checks `PRAGMA cipher_version`. If SQLCipher is not active, the store refuses to open rather than write plaintext.
 *
 * Key: a 256-bit key is generated by SQLite's own random source (`randomblob`), applied before any other statement,
 * and kept in device secure storage. It is never shown or logged.
 *
 * Key loss: when the database exists but its key is gone or wrong, the first read fails. The store reports KEY_LOST and
 * never deletes the file or writes a new key over it. The only way back is "delete everything", which removes the file
 * and the key together.
 */

/** The subset of expo-sqlite this store uses. Injected in tests. */
export interface SqlDatabase {
  execAsync(source: string): Promise<void>;
  runAsync(source: string, params: readonly (string | number)[]): Promise<void>;
  getFirstAsync<T>(source: string, params: readonly (string | number)[]): Promise<T | null>;
  getAllAsync<T>(source: string, params: readonly (string | number)[]): Promise<T[]>;
  closeAsync(): Promise<void>;
}

/** The subset of expo-secure-store this store uses. Injected in tests. */
export interface KeyStorage {
  getItemAsync(key: string): Promise<string | null>;
  setItemAsync(
    key: string,
    value: string,
    options: { keychainAccessible: SecureStore.KeychainAccessibilityConstant },
  ): Promise<void>;
  deleteItemAsync(key: string): Promise<void>;
}

export interface NativeMemoryDeps {
  readonly keys: KeyStorage;
  openDatabase(name: string): Promise<SqlDatabase>;
  deleteDatabase(name: string): Promise<void>;
  /** A 64-character lower-case hex key from SQLite's random source. */
  randomKeyHex(): Promise<string>;
}

interface StoredRow {
  readonly id: string;
  readonly createdAt: number;
  readonly body: string;
}

export interface NativeMemoryStore {
  newId(): Promise<string>;
  save(row: StoredRow): Promise<void>;
  /** Stored bodies, newest first. */
  list(): Promise<string[]>;
  remove(id: string): Promise<void>;
  /** Deletes every row, the database file and its key. */
  removeAll(): Promise<void>;
}

export const MEMORY_DB_NAME = "lensmate-memory.db";
export const MEMORY_KEY_NAME = "lensmate.memory.key";
const KEY_PATTERN = /^[0-9a-f]{64}$/;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS items (
  id TEXT PRIMARY KEY NOT NULL,
  created_at INTEGER NOT NULL,
  body TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS items_created_at ON items (created_at);
`;

export function createNativeMemoryStore(deps: NativeMemoryDeps): NativeMemoryStore {
  let connection: Promise<SqlDatabase> | undefined;

  async function readKey(): Promise<string | null> {
    let stored: string | null;
    try {
      stored = await deps.keys.getItemAsync(MEMORY_KEY_NAME);
    } catch {
      throw new MemoryStoreError("UNAVAILABLE");
    }
    if (stored !== null && !KEY_PATTERN.test(stored)) {
      throw new MemoryStoreError("KEY_LOST");
    }
    return stored;
  }

  async function open(): Promise<SqlDatabase> {
    const stored = await readKey();
    const keyHex = stored ?? (await deps.randomKeyHex());
    let db: SqlDatabase;
    try {
      db = await deps.openDatabase(MEMORY_DB_NAME);
    } catch {
      throw new MemoryStoreError("UNAVAILABLE");
    }
    try {
      // The key must be the first statement. Nothing is read or written before it.
      await db.execAsync(`PRAGMA key = "x'${keyHex}'";`);
      const cipher = await db.getFirstAsync<{ cipher_version: string | null }>(
        "PRAGMA cipher_version",
        [],
      );
      if (!cipher?.cipher_version) {
        throw new MemoryStoreError("NOT_ENCRYPTED");
      }
      await db.execAsync("PRAGMA secure_delete = ON;");
      try {
        await db.getFirstAsync("SELECT count(*) AS n FROM sqlite_master", []);
      } catch {
        // A wrong or lost key shows up here: the file cannot be read at all.
        throw new MemoryStoreError("KEY_LOST");
      }
      if (stored === null) {
        await deps.keys.setItemAsync(MEMORY_KEY_NAME, keyHex, {
          keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
        });
      }
      await db.execAsync(SCHEMA);
      return db;
    } catch (error) {
      await db.closeAsync().catch(() => undefined);
      if (error instanceof MemoryStoreError) {
        throw error;
      }
      throw new MemoryStoreError("FAILED");
    }
  }

  // Once the store has refused for a lasting reason (no SQLCipher, or a lost key), later calls fail at once instead of
  // reopening the database each time. Only "delete everything" clears this, so an unsupported build does not retry.
  let refused: MemoryStoreError | undefined;

  function connect(): Promise<SqlDatabase> {
    if (refused !== undefined) {
      return Promise.reject(refused);
    }
    connection ??= open().catch((error: unknown) => {
      connection = undefined;
      if (
        error instanceof MemoryStoreError &&
        (error.failure === "NOT_ENCRYPTED" || error.failure === "KEY_LOST")
      ) {
        refused = error;
      }
      throw error;
    });
    return connection;
  }

  async function run<T>(work: (db: SqlDatabase) => Promise<T>): Promise<T> {
    const db = await connect();
    try {
      return await work(db);
    } catch (error) {
      if (error instanceof MemoryStoreError) {
        throw error;
      }
      throw new MemoryStoreError("FAILED");
    }
  }

  return {
    async newId() {
      return run(async (db) => {
        const row = await db.getFirstAsync<{ id: string }>(
          "SELECT lower(hex(randomblob(16))) AS id",
          [],
        );
        if (row === null) {
          throw new MemoryStoreError("FAILED");
        }
        return row.id;
      });
    },

    save(row) {
      return run((db) =>
        db.runAsync("INSERT OR REPLACE INTO items (id, created_at, body) VALUES (?, ?, ?)", [
          row.id,
          row.createdAt,
          row.body,
        ]),
      );
    },

    list() {
      return run(async (db) => {
        const rows = await db.getAllAsync<{ body: string }>(
          "SELECT body FROM items ORDER BY created_at DESC",
          [],
        );
        return rows.map((r) => r.body);
      });
    },

    remove(id) {
      return run((db) => db.runAsync("DELETE FROM items WHERE id = ?", [id]));
    },

    async removeAll() {
      // Works even when the key is lost: it removes the file and the key, and nothing is read first.
      const current = connection;
      connection = undefined;
      if (current !== undefined) {
        await current.then((db) => db.closeAsync()).catch(() => undefined);
      }
      await deps.deleteDatabase(MEMORY_DB_NAME);
      await deps.keys.deleteItemAsync(MEMORY_KEY_NAME);
      refused = undefined;
    },
  };
}

/** expo-sqlite is loaded only when a phone opens memory, so the web build never evaluates the native module. */
async function openExpoDatabase(name: string): Promise<SqlDatabase> {
  const SQLite = await import("expo-sqlite");
  const db = await SQLite.openDatabaseAsync(name);
  return {
    execAsync: (source) => db.execAsync(source),
    runAsync: async (source, params) => {
      await db.runAsync(source, [...params]);
    },
    getFirstAsync: (source, params) => db.getFirstAsync(source, [...params]),
    getAllAsync: (source, params) => db.getAllAsync(source, [...params]),
    closeAsync: () => db.closeAsync(),
  };
}

async function randomKeyHex(): Promise<string> {
  // An in-memory database is used only to ask SQLite for random bytes; nothing is written to the phone.
  const scratch = await openExpoDatabase(":memory:");
  try {
    const row = await scratch.getFirstAsync<{ k: string }>(
      "SELECT lower(hex(randomblob(32))) AS k",
      [],
    );
    if (row === null || !KEY_PATTERN.test(row.k)) {
      throw new MemoryStoreError("FAILED");
    }
    return row.k;
  } finally {
    await scratch.closeAsync().catch(() => undefined);
  }
}

function expoNativeMemoryDeps(): NativeMemoryDeps {
  return {
    keys: SecureStore,
    openDatabase: openExpoDatabase,
    deleteDatabase: async (name) => {
      const SQLite = await import("expo-sqlite");
      await SQLite.deleteDatabaseAsync(name);
    },
    randomKeyHex,
  };
}

let shared: NativeMemoryStore | undefined;

/** The one store the phone uses. Created on first use, so a web build never reaches it. */
export function nativeMemory(): NativeMemoryStore {
  shared ??= createNativeMemoryStore(expoNativeMemoryDeps());
  return shared;
}
